            latency_so_far_s = rel_time_s - query_entry.rel_start_time_s
        iconq_predicted_latencies[cluster_name][query_id] = max(
            pred.overall_mean_s(),
            prev_latency_prediction_s,
            latency_so_far_s,
        )
